/**
 * Structured learning activities generated by the shared tutoring engine.
 * For each kind: the JSON shape the model must produce (Zod), the task instructions,
 * a plain-text rendering for the validator, and the split between what the student
 * sees (`content`) and what stays on the server (`solution`: answers, rubrics).
 */
import { z } from "zod";

export const ACTIVITY_KINDS = ["quiz", "summary", "mindmap", "flashcards", "keyterms", "teachback", "game", "diagnostic"] as const;
export type ActivityKind = (typeof ACTIVITY_KINDS)[number];

const text = (max: number) => z.string().trim().min(1).max(max);
const hint = z.string().trim().max(300).optional();

// ── quiz / diagnostic ──
const McQ = z.object({
  type: z.literal("mc"),
  prompt: text(500),
  options: z.array(text(200)).min(2).max(5),
  answer: z.coerce.number().int().min(0),
  explanation: text(800),
  hint,
});
const TfQ = z.object({
  type: z.literal("tf"),
  prompt: text(500),
  answer: z.union([z.boolean(), z.enum(["true", "false"]).transform((v) => v === "true")]),
  explanation: text(800),
  hint,
});
const ShortQ = z.object({ type: z.literal("short"), prompt: text(500), answer: text(200), explanation: text(800), hint });
export const QuizSchema = z.object({
  questions: z
    .array(z.discriminatedUnion("type", [McQ, TfQ, ShortQ]))
    .min(2)
    .max(10)
    .refine((qs) => qs.every((q) => q.type !== "mc" || q.answer < q.options.length), "mc answer index out of range"),
});

// ── summary ──
export const SummarySchema = z.object({
  title: text(160),
  overview: text(1500),
  mainIdeas: z.array(text(400)).min(1).max(8),
  concepts: z.array(z.object({ name: text(120), explanation: text(600) })).max(8).default([]),
  definitions: z.array(z.object({ term: text(120), definition: text(400) })).max(10).default([]),
  takeaways: z.array(text(300)).min(1).max(6),
});

// ── mind map ──
export const MindMapSchema = z.object({
  center: text(80),
  branches: z
    .array(
      z.object({
        label: text(80),
        summary: z.string().trim().max(240).optional(),
        children: z.array(z.object({ label: text(80), detail: z.string().trim().max(240).optional() })).min(1).max(5),
      }),
    )
    .min(2)
    .max(6),
  links: z.array(z.object({ from: text(80), to: text(80), label: z.string().trim().max(60).optional() })).max(6).default([]),
});

// ── flashcards ──
export const FlashcardsSchema = z.object({
  cards: z.array(z.object({ front: text(300), back: text(600), hint })).min(3).max(15),
});

// ── key terms ──
export const KeyTermsSchema = z.object({
  terms: z
    .array(
      z.object({
        term: text(80),
        definition: text(400),
        example: text(400),
        related: z.array(text(60)).max(5).default([]),
        pronunciation: z.string().trim().max(80).optional(),
      }),
    )
    .min(3)
    .max(12),
});

// ── teach me back (introduction + hidden rubric) ──
export const TeachBackSchema = z.object({
  introduction: text(1500),
  prompt: text(300),
  keyPoints: z.array(text(300)).min(2).max(6),
});

// ── STEM game level ──
const MatchC = z.object({
  type: z.literal("match"),
  instructions: text(300),
  pairs: z.array(z.object({ left: text(120), right: text(160) })).min(3).max(6),
  explanation: text(600),
});
const SequenceC = z.object({
  type: z.literal("sequence"),
  instructions: text(300),
  steps: z.array(text(200)).min(3).max(6),
  explanation: text(600),
});
const ChoiceC = z.object({
  type: z.literal("choice"),
  prompt: text(500),
  options: z.array(text(200)).min(2).max(4),
  answer: z.coerce.number().int().min(0),
  explanation: text(600),
  hint,
});
export const GameSchema = z.object({
  title: text(120),
  story: z.string().trim().max(500).optional(),
  challenges: z
    .array(z.discriminatedUnion("type", [MatchC, SequenceC, ChoiceC]))
    .min(2)
    .max(4)
    .refine((cs) => cs.every((c) => c.type !== "choice" || c.answer < c.options.length), "choice answer index out of range"),
});

export const ACTIVITY_SCHEMAS = {
  quiz: QuizSchema,
  diagnostic: QuizSchema,
  summary: SummarySchema,
  mindmap: MindMapSchema,
  flashcards: FlashcardsSchema,
  keyterms: KeyTermsSchema,
  teachback: TeachBackSchema,
  game: GameSchema,
} as const;

export interface ActivityOptions {
  difficulty?: "easy" | "medium" | "hard";
  length?: "short" | "standard" | "detailed";
  count?: number;
  level?: number;
}

const SHAPES: Record<ActivityKind, string> = {
  quiz: `{"questions": [ {"type":"mc","prompt":string,"options":[string,...],"answer":<index of the correct option, 0-based>,"explanation":string,"hint":string}, {"type":"tf","prompt":string,"answer":true|false,"explanation":string,"hint":string}, {"type":"short","prompt":string,"answer":"<short expected answer, a number or a few words>","explanation":string,"hint":string} ]}`,
  diagnostic: "",
  summary: `{"title":string,"overview":string,"mainIdeas":[string],"concepts":[{"name":string,"explanation":string}],"definitions":[{"term":string,"definition":string}],"takeaways":[string]}`,
  mindmap: `{"center":string,"branches":[{"label":string,"summary":string,"children":[{"label":string,"detail":string}]}],"links":[{"from":"<a branch or child label>","to":"<another label>","label":string}]}`,
  flashcards: `{"cards":[{"front":"<question or cue>","back":"<answer>","hint":string}]}`,
  keyterms: `{"terms":[{"term":string,"definition":"<simple definition>","example":string,"related":[string],"pronunciation":"<how to say it, only if useful>"}]}`,
  teachback: `{"introduction":"<a short lesson introducing the concept>","prompt":"<one question asking the student to explain it in their own words>","keyPoints":["<an essential idea a good explanation contains>"]}`,
  game: `{"title":string,"story":"<one-sentence mission framing>","challenges":[ {"type":"match","instructions":string,"pairs":[{"left":string,"right":string}],"explanation":string}, {"type":"sequence","instructions":string,"steps":["<steps in the CORRECT order>"],"explanation":string}, {"type":"choice","prompt":string,"options":[string],"answer":<index>,"explanation":string,"hint":string} ]}`,
};
SHAPES.diagnostic = SHAPES.quiz;

export function activityTask(kind: ActivityKind, topic: string, o: ActivityOptions): string {
  const n = Math.max(3, Math.min(10, o.count ?? 5));
  const lines: Record<ActivityKind, string> = {
    quiz: `Create a ${o.difficulty ?? "medium"} quiz of ${n} questions about "${topic}". Mix multiple-choice, true/false and short-answer questions. Each question must have exactly one correct, unambiguous answer, a hint that helps without giving the answer away, and an explanation of WHY the answer is correct and why the tempting wrong answers are wrong.`,
    diagnostic: `Create a short diagnostic of 4 questions about "${topic}" of increasing difficulty (easy, easy, medium, hard) to find the student's level. Use multiple-choice and true/false. Each needs one correct answer, a hint and an explanation.`,
    summary: `Write a ${o.length ?? "standard"} summary of "${topic}" (very short: a few lines and 2-3 main ideas; standard: clear and complete; detailed: thorough with concepts and definitions). Use simple, accurate language.`,
    mindmap: `Build a mind map of "${topic}": one central concept, 3-6 main branches, 1-5 short subtopics per branch, and up to 4 cross-links between related ideas. Labels must be short (max 6 words).`,
    flashcards: `Create ${Math.max(5, n)} flashcards about "${topic}". Front: a clear question or cue. Back: a concise, correct answer.`,
    keyterms: `List the ${Math.max(5, n)} most important key terms for "${topic}", each with a simple definition, a concrete example and related terms.`,
    teachback: `Prepare a "teach me back" activity on "${topic}": a short, clear introduction of the concept, then one prompt inviting the student to explain it in their own words, and the 2-6 key points a good explanation should contain (the student will not see them).`,
    game: `Design level ${o.level ?? 1} of an educational game about "${topic}" with 3 challenges: one "match" (3-6 pairs), one "sequence" (3-6 steps in the correct order) and one "choice" mission. Difficulty must increase with the level number (level 1 = gentle). Make it fun and correct.`,
  };
  return [
    `TASK: ${lines[kind]}`,
    "Respond with ONLY a JSON object, no prose before or after, with this shape:",
    SHAPES[kind],
    "All facts, answers and calculations MUST be correct. Write all student-facing text in the reply language.",
  ].join("\n");
}

/** Plain-text rendering that the validator model and arithmetic checker inspect. */
const LETTERS = "ABCDE";

function renderChoice(prompt: string, options: string[], answer: number, explanation: string): string[] {
  return [
    prompt,
    ...options.map((o, i) => `  ${LETTERS[i]}) ${o}`),
    `  MARKED CORRECT: ${LETTERS[answer]}) ${options[answer]}`,
    `  Explanation: ${explanation}`,
  ];
}

/**
 * Readable rendering for the validator: answer keys are spelled out ("MARKED CORRECT: B) 2/3")
 * instead of bare indexes, which small reviewer models cannot map reliably.
 */
export function renderForReview(kind: ActivityKind, data: unknown): string {
  if (kind === "quiz" || kind === "diagnostic") {
    const q = data as z.infer<typeof QuizSchema>;
    const lines = q.questions.flatMap((x, i) => {
      const head = `Q${i + 1}`;
      if (x.type === "mc") return [`${head} (multiple choice, exactly one correct option):`, ...renderChoice(x.prompt, x.options, x.answer, x.explanation)];
      if (x.type === "tf") return [`${head} (true/false): ${x.prompt}`, `  MARKED ANSWER: ${x.answer ? "true" : "false"}`, `  Explanation: ${x.explanation}`];
      return [`${head} (short answer): ${x.prompt}`, `  EXPECTED ANSWER: ${x.answer}`, `  Explanation: ${x.explanation}`];
    });
    return lines.join("\n").slice(0, 7000);
  }
  if (kind === "game") {
    const g = data as z.infer<typeof GameSchema>;
    const lines = [`Game: ${g.title}`, ...(g.story ? [g.story] : [])];
    g.challenges.forEach((c, i) => {
      const head = `Challenge ${i + 1}`;
      if (c.type === "choice") lines.push(`${head} (choose exactly one):`, ...renderChoice(c.prompt, c.options, c.answer, c.explanation));
      else if (c.type === "match") lines.push(`${head} (match pairs): ${c.instructions}`, ...c.pairs.map((p) => `  ${p.left} = ${p.right}`), `  Explanation: ${c.explanation}`);
      else lines.push(`${head} (put in order): ${c.instructions}`, ...c.steps.map((st, j) => `  ${j + 1}. ${st}`), `  Explanation: ${c.explanation}`);
    });
    return lines.join("\n").slice(0, 7000);
  }
  return JSON.stringify(data, null, 1).slice(0, 7000);
}

/** Numeric value of a plain option such as "1/2", "0.5", "50%", "-3" (null for anything else). */
export function optionValue(option: string): number | null {
  // strip spaces, $, backslashes and parentheses so "\( \frac{1}{2} \)" becomes "frac{1}{2}"
  const s = option.replace(/[\s$\\()]/g, "").replace(",", ".");
  let m = /^(-?\d+(?:\.\d+)?)\/(-?\d+(?:\.\d+)?)$/.exec(s);
  if (m) return Number(m[2]) === 0 ? null : Number(m[1]) / Number(m[2]);
  m = /^d?frac\{(-?\d+)\}\{(-?\d+)\}$/.exec(s);
  if (m) return Number(m[2]) === 0 ? null : Number(m[1]) / Number(m[2]);
  m = /^(-?\d+(?:\.\d+)?)%$/.exec(s);
  if (m) return Number(m[1]) / 100;
  m = /^-?\d+(?:\.\d+)?$/.exec(s);
  return m ? Number(s) : null;
}

function duplicateOptions(options: string[]): [number, number] | null {
  for (let i = 0; i < options.length; i++) {
    for (let j = i + 1; j < options.length; j++) {
      const a = options[i].trim().toLowerCase();
      const b = options[j].trim().toLowerCase();
      if (a === b) return [i, j];
      const va = optionValue(options[i]);
      const vb = optionValue(options[j]);
      if (va !== null && vb !== null && Math.abs(va - vb) < 1e-9) return [i, j];
    }
  }
  return null;
}

/** Deterministic checks run before the reviewer model: a choice question must have exactly one right option. */
export function activityIssues(kind: ActivityKind, data: unknown): string[] {
  const choices: { label: string; options: string[] }[] = [];
  if (kind === "quiz" || kind === "diagnostic") {
    (data as z.infer<typeof QuizSchema>).questions.forEach((q, i) => {
      if (q.type === "mc") choices.push({ label: `Question ${i + 1}`, options: q.options });
    });
  } else if (kind === "game") {
    (data as z.infer<typeof GameSchema>).challenges.forEach((c, i) => {
      if (c.type === "choice") choices.push({ label: `Challenge ${i + 1}`, options: c.options });
    });
  }
  const issues: string[] = [];
  for (const c of choices) {
    const d = duplicateOptions(c.options);
    if (d) issues.push(`${c.label}: options "${c.options[d[0]]}" and "${c.options[d[1]]}" are equal, so more than one option is correct. Every option except one must be wrong.`);
  }
  return issues;
}

function shuffle<T>(items: T[], seed: string): { items: T[]; order: number[] } {
  // deterministic shuffle so the same item renders the same way, but never the solved order
  let h = 2166136261;
  for (const c of seed) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  const order = items.map((_, i) => i);
  for (let i = order.length - 1; i > 0; i--) {
    h = Math.imul(h ^ (h >>> 15), 2246822507);
    const j = Math.abs(h) % (i + 1);
    [order[i], order[j]] = [order[j], order[i]];
  }
  if (order.every((v, i) => v === i) && order.length > 1) order.push(order.shift()!);
  return { items: order.map((i) => items[i]), order };
}

/** Split validated output into student-visible content and server-only solution. */
export function splitActivity(kind: ActivityKind, data: unknown, seed: string): { content: object; solution: object } {
  switch (kind) {
    case "quiz":
    case "diagnostic": {
      const q = data as z.infer<typeof QuizSchema>;
      return {
        content: {
          questions: q.questions.map((x) =>
            x.type === "mc"
              ? { type: x.type, prompt: x.prompt, options: x.options, hint: x.hint }
              : { type: x.type, prompt: x.prompt, hint: x.hint },
          ),
        },
        solution: { questions: q.questions.map((x) => ({ type: x.type, answer: x.answer, explanation: x.explanation })) },
      };
    }
    case "teachback": {
      const t = data as z.infer<typeof TeachBackSchema>;
      return { content: { introduction: t.introduction, prompt: t.prompt }, solution: { keyPoints: t.keyPoints } };
    }
    case "game": {
      const g = data as z.infer<typeof GameSchema>;
      const contentChallenges: object[] = [];
      const solutionChallenges: object[] = [];
      g.challenges.forEach((c, i) => {
        if (c.type === "match") {
          const rights = shuffle(
            c.pairs.map((p) => p.right),
            `${seed}:${i}`,
          );
          contentChallenges.push({ type: "match", instructions: c.instructions, left: c.pairs.map((p) => p.left), right: rights.items });
          // for left i, the correct right is at position rights.order.indexOf(i)
          solutionChallenges.push({ type: "match", answer: c.pairs.map((_, li) => rights.order.indexOf(li)), explanation: c.explanation });
        } else if (c.type === "sequence") {
          const s = shuffle(c.steps, `${seed}:${i}`);
          contentChallenges.push({ type: "sequence", instructions: c.instructions, steps: s.items });
          // correct order expressed as indexes into the shuffled list
          solutionChallenges.push({ type: "sequence", answer: c.steps.map((_, k) => s.order.indexOf(k)), explanation: c.explanation });
        } else {
          contentChallenges.push({ type: "choice", prompt: c.prompt, options: c.options, hint: c.hint });
          solutionChallenges.push({ type: "choice", answer: c.answer, explanation: c.explanation });
        }
      });
      return { content: { title: g.title, story: g.story, challenges: contentChallenges }, solution: { challenges: solutionChallenges } };
    }
    default:
      return { content: data as object, solution: {} };
  }
}
